class Solution {
public:
    int numberOfCategories(int n, CategoryHandler* categoryHandler) {
        vector<int> representatives;
        for (int i = 0; i < n; ++i) {
            bool matched = false;
            for (int r : representatives) {
                if (categoryHandler->haveSameCategory(i, r)) {
                    matched = true;
                    break;
                }
            }
            if (!matched) {
                representatives.push_back(i);
            }
        }
        return representatives.size();
    }
};

import java.util.ArrayList;
import java.util.List;

class Solution {
    public int numberOfCategories(int n, CategoryHandler categoryHandler) {
        List<Integer> representatives = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            boolean matched = false;
            for (int r : representatives) {
                if (categoryHandler.haveSameCategory(i, r)) {
                    matched = true;
                    break;
                }
            }
            if (!matched) {
                representatives.add(i);
            }
        }
        return representatives.size();
    }
}

/**
 * @param {number} n
 * @param {CategoryHandler} categoryHandler
 * @return {number}
 */
var numberOfCategories = function(n, categoryHandler) {
    const representatives = [];
    for (let i = 0; i < n; i++) {
        let matched = false;
        for (const r of representatives) {
            if (categoryHandler.haveSameCategory(i, r)) {
                matched = true;
                break;
            }
        }
        if (!matched) {
            representatives.push(i);
        }
    }
    return representatives.length;
};
